    "new": "pub(crate) fn analyze_retry(events: &[JournalEvent]) -> RetryAnalysis {
    let state = events.iter().fold(
        (None, None),
        |(last_successful, pending), event| {
            match event {
                JournalEvent::StepStarted { step, .. } => (last_successful, Some(step.get())),
                JournalEvent::ActionFailedEvent { step, .. } => (last_successful, Some(step.get())),
                JournalEvent::StepSucceeded { step, .. } => {
                    let new_pending = if pending == Some(step.get()) { None } else { pending };
                    (Some(step.get()), new_pending)
                }
                _ => (last_successful, pending),
            }
        },
    );

    let (last_successful_step, pending_step) = state;

    let is_failed = matches!(
        events.last(),
        Some(JournalEvent::RunFailedEvent { .. })
    );

    if !is_failed {
        return RetryAnalysis {
            failed_at_step: None,
            last_successful_step,
            can_retry: false,
            reason: "run did not fail (no retry needed)".into(),
        };
    }

    RetryAnalysis {
        failed_at_step: pending_step,
        last_successful_step,
        can_retry: true,
        reason: String::new(),
    }
}"
